import { lazy } from 'react';
import { useConvertToTokenFunnel } from '~/widgets/exchange-convert-to-token-funnel/lib/use-convert-to-token-funnel';
import { FunnelStep } from '~/widgets/exchange-convert-to-token-funnel/model/enums';
import {
  금액입력Context,
  금액확인Context,
  완료Context,
  처리중Context,
} from '~/widgets/exchange-convert-to-token-funnel/model/schemas';
import { ExchangeFunnelProps } from '~/widgets/exchange-funnel-router/ui/exchange-funnel-router';

const InputAmountPage = lazy(() =>
  import('./input-amount-page').then((module) => ({ default: module.InputAmountPage })),
);
const InputConfirmPage = lazy(() =>
  import('./input-confirm-page').then((module) => ({ default: module.InputConfirmPage })),
);
const ProcessPage = lazy(() => import('./process-page').then((module) => ({ default: module.ProcessPage })));
const CompletePage = lazy(() => import('./complete-page').then((module) => ({ default: module.CompletePage })));

export const ConvertToTokenFunnel = ({
  config,
  onProcessingStart,
  onProcessingSuccess,
  onProcessingError,
  onComplete,
}: ExchangeFunnelProps) => {
  const { funnel } = useConvertToTokenFunnel({
    step: FunnelStep.금액입력,
    context: {
      ...config,
    },
  });

  return (
    <funnel.Render
      금액입력={({ context, history }) => (
        <InputAmountPage
          context={context as 금액입력Context}
          onNext={({ txCd, trnscAmt }) => {
            history.push(FunnelStep.금액확인, {
              ...context,
              txCd,
              trnscAmt,
            });
          }}
          onError={(error) => {
            console.error('[ExchangeFunnel] 금액입력 error:', error);
            onProcessingError?.(error);
          }}
        />
      )}
      금액확인={({ context, history }) => (
        <InputConfirmPage
          context={context as 금액확인Context}
          onNext={() => {
            onProcessingStart?.();
            history.push(FunnelStep.처리중, { ...context });
          }}
          onError={(error) => {
            onProcessingError?.(error);
          }}
        />
      )}
      처리중={({ context, history }) => (
        <ProcessPage
          context={context as 처리중Context}
          onNext={({ trnscId, reqAliasNm }) => {
            onProcessingSuccess?.(trnscId);
            history.push(FunnelStep.완료, {
              ...context,
              trnscId,
              reqAliasNm,
            });
          }}
          onError={(error) => {
            onProcessingError?.(error);
          }}
        />
      )}
      완료={({ context }) => (
        <CompletePage
          context={context as 완료Context}
          onNext={({ redirectPath }) => {
            onComplete?.(redirectPath);
          }}
          onError={(error) => {
            onProcessingError?.(error);
          }}
        />
      )}
    />
  );
};
