import { useFunnel } from '@use-funnel/react-router-dom';
import { FunnelStep } from '~/widgets/exchange-convert-to-token-funnel/model/enums';
import {
  금액입력_Schema,
  금액확인_Schema,
  완료_Schema,
  FunnelContextMap,
  처리중_Schema,
} from '~/widgets/exchange-convert-to-token-funnel/model/schemas';
import { BaseExchangeContext } from '~/entities/exchange';

export const useConvertToTokenFunnel = (initialConfig?: {
  step?: FunnelStep;
  context?: Partial<BaseExchangeContext>;
}) => {
  const initialStep = initialConfig?.step || FunnelStep.금액입력;
  const initialContext = {
    ...(initialConfig?.context || {}),
  };

  const funnel = useFunnel<FunnelContextMap>({
    id: 'convert-to-token-funnel',
    steps: {
      [FunnelStep.금액입력]: { parse: 금액입력_Schema.parse },
      [FunnelStep.금액확인]: { parse: 금액확인_Schema.parse },
      [FunnelStep.처리중]: { parse: 처리중_Schema.parse },
      [FunnelStep.완료]: { parse: 완료_Schema.parse },
    },
    initial: {
      step: initialStep,
      context: initialContext,
    },
  });

  return {
    funnel,
  };
};
