import { z } from 'zod';
import { BaseExchangeContext, BaseExchangeContextSchema } from '~/entities/exchange/model/schemas';
import { FunnelStep } from './enums';

export const 금액입력_Schema = BaseExchangeContextSchema.required({
  tokenId: true,
  trnscTypeCd: true,
});

export const 금액확인_Schema = 금액입력_Schema.required({
  txCd: true,
  trnscAmt: true,
});

export const 처리중_Schema = 금액확인_Schema;

export const 완료_Schema = 처리중_Schema.required({
  trnscId: true,
  redirectPath: true,
});

export type 금액입력Context = z.infer<typeof 금액입력_Schema>;
export type 금액확인Context = z.infer<typeof 금액확인_Schema>;
export type 처리중Context = z.infer<typeof 처리중_Schema>;
export type 완료Context = z.infer<typeof 완료_Schema>;

export type FunnelContextMap = {
  [FunnelStep.금액입력]: BaseExchangeContext;
  [FunnelStep.금액확인]: BaseExchangeContext;
  [FunnelStep.처리중]: BaseExchangeContext;
  [FunnelStep.완료]: BaseExchangeContext;
};
